<?php
require_once __DIR__.'/../config/config.php';require_role(['teacher','admin']);$u=current_user();$id=(int)($_GET['id']??0);$course=null;
if($id){$s=db()->prepare("SELECT * FROM courses WHERE id=? AND (teacher_id=? OR ?)");$s->execute([$id,$u['id'],$u['role']==='admin'?1:0]);$course=$s->fetch();if(!$course)exit('Course not found or access denied.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=[trim($_POST['title']??''),trim($_POST['language_name']??''),trim($_POST['language_code']??''),trim($_POST['native_name']??''),trim($_POST['flag_emoji']??'🌐'),$_POST['level']??'Beginner',trim($_POST['description']??''),(int)isset($_POST['is_published'])];if(!$data[0]||!$data[1]||!$data[2]){flash('Title, language and language code are required.','error');redirect('/teacher/course-edit.php'.($id?'?id='.$id:''));}if($id){$s=db()->prepare("UPDATE courses SET title=?,language_name=?,language_code=?,native_name=?,flag_emoji=?,level=?,description=?,is_published=? WHERE id=?");$s->execute([...$data,$id]);}else{$s=db()->prepare("INSERT INTO courses(title,language_name,language_code,native_name,flag_emoji,level,description,is_published,teacher_id) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([...$data,$u['id']]);$id=(int)db()->lastInsertId();}flash('Course saved.');redirect('/teacher/course-edit.php?id='.$id);}
$page_title='Manage course — LinguaFree';include __DIR__.'/../includes/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">COURSE BUILDER</span><h1><?= $course?'Edit course':'Create a course' ?></h1></div><a class="btn btn-outline" href="<?= BASE_URL ?>/teacher/index.php">Back</a></div>
<form class="form-card" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-grid"><label>Course title<input name="title" required value="<?= e($course['title']??'') ?>"></label><label>Language name<input name="language_name" required value="<?= e($course['language_name']??'') ?>"></label><label>Language code<input name="language_code" required maxlength="12" value="<?= e($course['language_code']??'') ?>"></label><label>Native name<input name="native_name" value="<?= e($course['native_name']??'') ?>"></label><label>Flag emoji<input name="flag_emoji" value="<?= e($course['flag_emoji']??'🌐') ?>"></label><label>Level<select name="level"><?php foreach(['Beginner','Intermediate','Advanced'] as $v): ?><option <?= ($course['level']??'Beginner')===$v?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label></div><label>Description<textarea name="description" rows="4"><?= e($course['description']??'') ?></textarea></label><label class="check"><input type="checkbox" name="is_published" value="1" <?= !empty($course['is_published'])?'checked':'' ?>> Publish course (visible to students)</label><button class="btn btn-primary">Save course →</button></form>
<?php if($course): ?><div class="page-head compact"><div><h2>Lessons</h2><p>Add and manage the course curriculum.</p></div><a class="btn btn-primary" href="<?= BASE_URL ?>/teacher/lesson-edit.php?course_id=<?= $id ?>">+ Add lesson</a></div><?php $s=db()->prepare("SELECT * FROM lessons WHERE course_id=? ORDER BY lesson_order");$s->execute([$id]);foreach($s as $l): ?><div class="list-row"><span><?= (int)$l['lesson_order'] ?>. <?= e($l['title']) ?></span><a href="<?= BASE_URL ?>/teacher/lesson-edit.php?id=<?= (int)$l['id'] ?>">Edit lesson →</a></div><?php endforeach; endif; ?>
<?php include __DIR__.'/../includes/footer.php'; ?>